// Registro del evento + texto del aviso.
//
// Lo que llega de Noxus ya viene con la fecha y la hora LOCALES de la casa
// resueltas, asi que aqui no hay que pelearse con zonas horarias.
//
// El objeto `registro` es la fila del evento: si manana quieres volcarla a
// Google Sheets, a Postgres o a un Airtable, enchufa ese nodo detras de este
// y mapea `registro` — no hace falta tocar nada mas.

const salida = [];

for (const item of $input.all()) {
  const e = item.json.body ?? item.json;

  const encendida = e.accion === 'LUZ_ENCENDIDA';
  const verbo = encendida ? 'encendido' : 'apagado';

  // ── El registro del evento ──────────────────────────────────────────
  const registro = {
    evento_id: e.evento_id,
    fecha: e.fecha,
    hora: e.hora,
    timestamp: e.timestamp,
    usuario: e.usuario,
    accion: e.accion,
    accion_legible: e.accion_legible,
    elemento: e.elemento,
    entidad: e.entidad,
    categoria: e.categoria,
    origen: e.origen,
  };

  // ── ¿Hay un equipo al que avisar? ───────────────────────────────────
  // "sistema" es lo que dispara el propio panel (una automatizacion, un
  // sensor); "desconocido", una pestana sin avisos activados. Ninguno de los
  // dos es un movil al que se le pueda mandar nada.
  // Sin los segundos: en un aviso del movil «a las 21:00» se lee, y
  // «a las 21:00:39» solo hace ruido.
  const hhmm = (e.hora || '').slice(0, 5);

  const usuario = (e.usuario || '').trim();
  const avisar = usuario !== '' &&
                 !['sistema', 'desconocido'].includes(usuario.toLowerCase());

  salida.push({
    json: {
      registro,
      avisar,
      destino: usuario,
      titulo: `Luz ${encendida ? 'encendida' : 'apagada'}`,
      mensaje: `Has ${verbo} «${e.elemento}» a las ${hhmm}.`,
      // Un tag por luz: encender y apagar la misma lampara varias veces
      // refresca el mismo aviso en el movil en vez de apilar diez.
      tag: `n8n:luz:${e.entidad}`,
      url: '/panel?vista=logs',
    },
  });
}

return salida;
